class PythonFlowTracer {
  constructor() {
    this.maxSteps = 250;
  }

  trace(sourceCode) {
    const rawLines = sourceCode.replace(/\r\n/g, "\n").split("\n");
    const statements = this.parseLines(rawLines);
    const cfg = this.buildControlFlowGraph(statements);

    const steps = [];
    const stdout = [];
    const functions = {};
    const callStack = [
      {
        frameName: "Global Frame (main)",
        vars: {},
        prevVars: {}
      }
    ];

    try {
      this.executeBlock(statements, callStack, functions, steps, stdout);
    } catch (err) {
      steps.push({
        stepIndex: steps.length + 1,
        line: err.line || 1,
        nextLine: null,
        codeText: rawLines[(err.line || 1) - 1] || "",
        eventType: "ERROR",
        scopes: this.snapshotScopes(callStack, null),
        evalBreakdown: `Runtime Error: ${err.message}`,
        branchResult: null,
        stdout: [...stdout],
        explanations: {
          eli5: `Oops! Python ran into an error on line ${err.line || 1}: ${err.message}`,
          beginner: `Execution stopped on line ${err.line || 1} because of: ${err.message}`,
          deep: `Exception raised during statement evaluation: ${err.message}`,
          whyItHappened: `Check syntax or variable names on line ${err.line || 1}.`,
          whatNext: `Execution halted due to error.`
        },
        quiz: null
      });
    }

    // Populate nextLine and What Happens Next + Quiz for each step
    for (let i = 0; i < steps.length; i++) {
      const nextStep = i + 1 < steps.length ? steps[i + 1] : null;
      steps[i].nextLine = nextStep ? nextStep.line : null;
      steps[i].explanations.whatNext = nextStep
        ? `Next, Python moves to **Line ${nextStep.line}** (\`${nextStep.codeText.trim()}\`) to ${this.describeUpcomingAction(nextStep)}.`
        : `Program execution is complete! All statements have finished running.`;
      steps[i].quiz = this.generateQuizForStep(steps[i], nextStep);
    }

    return {
      rawLines,
      steps,
      cfg
    };
  }

  parseLines(rawLines) {
    const items = [];
    for (let i = 0; i < rawLines.length; i++) {
      const raw = rawLines[i];
      const strippedComment = this.stripInlineComment(raw);
      const trimmed = strippedComment.trim();
      if (!trimmed) continue;
      const indent = raw.match(/^\s*/)[0].length;
      items.push({
        line: i + 1,
        indent,
        text: trimmed,
        raw: raw
      });
    }
    return this.buildASTBlock(items, 0, items.length > 0 ? items[0].indent : 0).nodes;
  }

  stripInlineComment(line) {
    let inSingle = false;
    let inDouble = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === "'" && !inDouble) inSingle = !inSingle;
      else if (ch === '"' && !inSingle) inDouble = !inDouble;
      else if (ch === "#" && !inSingle && !inDouble) {
        return line.slice(0, i);
      }
    }
    return line;
  }

  buildASTBlock(items, startIdx, baseIndent) {
    const nodes = [];
    let i = startIdx;

    while (i < items.length) {
      const item = items[i];
      if (item.indent < baseIndent) break;

      if (item.text.startsWith("if ") && item.text.endsWith(":")) {
        const branches = [];
        const cond = item.text.slice(3, -1).trim();
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        branches.push({
          type: "if",
          line: item.line,
          text: item.text,
          condition: cond,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;

        while (i < items.length && items[i].indent === item.indent) {
          const cur = items[i];
          if (cur.text.startsWith("elif ") && cur.text.endsWith(":")) {
            const elifCond = cur.text.slice(5, -1).trim();
            const elifBody = this.parseChildSuite(items, i + 1, cur.indent);
            branches.push({
              type: "elif",
              line: cur.line,
              text: cur.text,
              condition: elifCond,
              body: elifBody.nodes
            });
            i = elifBody.nextIdx;
          } else if (cur.text === "else:") {
            const elseBody = this.parseChildSuite(items, i + 1, cur.indent);
            branches.push({
              type: "else",
              line: cur.line,
              text: cur.text,
              condition: null,
              body: elseBody.nodes
            });
            i = elseBody.nextIdx;
            break;
          } else {
            break;
          }
        }
        nodes.push({
          kind: "IF_CHAIN",
          line: item.line,
          text: item.text,
          branches
        });
      } else if (item.text.startsWith("for ") && item.text.endsWith(":")) {
        const header = item.text.slice(4, -1).trim();
        const inIdx = header.indexOf(" in ");
        const iterVar = header.slice(0, inIdx).trim();
        const iterExpr = header.slice(inIdx + 4).trim();
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        nodes.push({
          kind: "FOR",
          line: item.line,
          text: item.text,
          iterVar,
          iterExpr,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;
      } else if (item.text.startsWith("while ") && item.text.endsWith(":")) {
        const condition = item.text.slice(6, -1).trim();
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        nodes.push({
          kind: "WHILE",
          line: item.line,
          text: item.text,
          condition,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;
      } else if (item.text.startsWith("def ") && item.text.endsWith(":")) {
        const match = item.text.match(/^def\s+([a-zA-Z_]\w*)\s*\((.*)\)\s*:$/);
        const funcName = match ? match[1] : "func";
        const params = match && match[2].trim()
          ? match[2].split(",").map((s) => s.trim())
          : [];
        const bodyRes = this.parseChildSuite(items, i + 1, item.indent);
        nodes.push({
          kind: "DEF",
          line: item.line,
          text: item.text,
          funcName,
          params,
          body: bodyRes.nodes
        });
        i = bodyRes.nextIdx;
      } else {
        nodes.push({
          kind: "STMT",
          line: item.line,
          text: item.text
        });
        i++;
      }
    }

    return { nodes, nextIdx: i };
  }

  parseChildSuite(items, nextIdx, parentIndent) {
    if (nextIdx >= items.length || items[nextIdx].indent <= parentIndent) {
      return { nodes: [], nextIdx };
    }
    return this.buildASTBlock(items, nextIdx, items[nextIdx].indent);
  }

  executeBlock(nodes, callStack, functions, steps, stdout) {
    for (const node of nodes) {
      if (steps.length >= this.maxSteps) break;
      const ret = this.executeNode(node, callStack, functions, steps, stdout);
      if (ret && ret.returned) {
        return ret;
      }
    }
    return null;
  }

  executeNode(node, callStack, functions, steps, stdout) {
    const activeFrame = callStack[callStack.length - 1];

    if (node.kind === "DEF") {
      functions[node.funcName] = node;
      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: node.text,
        eventType: "FUNC_DEF",
        scopes: this.snapshotScopes(callStack, null),
        evalBreakdown: `Defined function ${node.funcName}(${node.params.join(", ")}) in memory`,
        branchResult: null,
        stdout: [...stdout],
        explanations: {
          eli5: `Python remembers a recipe called \`${node.funcName}\` so we can use it later! It doesn't run the lines inside yet.`,
          beginner: `Defines function \`${node.funcName}\` with parameters \`(${node.params.join(", ")})\`. The body will only execute when the function is called.`,
          deep: `Creates a function object bound to identifier \`${node.funcName}\` in the current scope without executing its suite.`,
          whyItHappened: `A \`def\` statement registers a reusable function block.`
        }
      });
      return null;
    }

    if (node.kind === "IF_CHAIN") {
      for (const branch of node.branches) {
        if (branch.type === "else") {
          steps.push({
            stepIndex: steps.length + 1,
            line: branch.line,
            codeText: branch.text,
            eventType: "CONDITION",
            scopes: this.snapshotScopes(callStack, null),
            evalBreakdown: `All previous conditions were False -> entering else block`,
            branchResult: true,
            stdout: [...stdout],
            explanations: {
              eli5: `None of the earlier \`if\` questions were true, so Python takes the fallback \`else\` path!`,
              beginner: `Since all preceding \`if\`/\`elif\` conditions evaluated to \`False\`, the \`else\` branch is executed.`,
              deep: `Fallback branch taken after exhaustive evaluation of prior conditional predicates.`,
              whyItHappened: `Every earlier condition in this \`if/elif\` chain was \`False\`.`
            }
          });
          return this.executeBlock(branch.body, callStack, functions, steps, stdout);
        } else {
          const val = Boolean(this.evalExpr(branch.condition, activeFrame.vars, functions, callStack, steps, stdout, branch.line));
          const substituted = this.substituteVarsInExpr(branch.condition, activeFrame.vars);
          steps.push({
            stepIndex: steps.length + 1,
            line: branch.line,
            codeText: branch.text,
            eventType: "CONDITION",
            scopes: this.snapshotScopes(callStack, null),
            evalBreakdown: `${branch.condition}  ==>  ${substituted}  ==>  ${val ? "True" : "False"}`,
            branchResult: val,
            stdout: [...stdout],
            explanations: {
              eli5: val
                ? `Python asks: Is \`${substituted}\` true? YES! So it goes inside this block.`
                : `Python asks: Is \`${substituted}\` true? NO (\`False\`). So it skips this block!`,
              beginner: `Evaluated condition \`${branch.condition}\` with current values (\`${substituted}\`), which is **${val ? "True" : "False"}**. ${val ? "Entering the indented block." : "Skipping to the next branch or statement."}`,
              deep: `Boolean predicate \`${branch.condition}\` resolved to \`${val ? "True" : "False"}\` via comparison operator evaluation.`,
              whyItHappened: `With current memory values, \`${substituted}\` evaluated to \`${val ? "True" : "False"}\`.`
            }
          });
          if (val) {
            return this.executeBlock(branch.body, callStack, functions, steps, stdout);
          }
        }
      }
      return null;
    }

    if (node.kind === "FOR") {
      const iterable = this.evalExpr(node.iterExpr, activeFrame.vars, functions, callStack, steps, stdout, node.line);
      const listItems = Array.isArray(iterable) ? iterable : [];

      for (let idx = 0; idx < listItems.length; idx++) {
        if (steps.length >= this.maxSteps) break;
        const itemVal = listItems[idx];
        const prevVal = activeFrame.vars[node.iterVar];
        const isNew = !(node.iterVar in activeFrame.vars);
        activeFrame.prevVars[node.iterVar] = prevVal;
        activeFrame.vars[node.iterVar] = itemVal;

        steps.push({
          stepIndex: steps.length + 1,
          line: node.line,
          codeText: node.text,
          eventType: "LOOP_ITER",
          scopes: this.snapshotScopes(callStack, {
            name: node.iterVar,
            status: isNew ? "new" : "updated",
            prevValue: prevVal
          }),
          evalBreakdown: `Iteration ${idx + 1} of ${listItems.length}: ${node.iterVar} = ${this.formatVal(itemVal)}`,
          branchResult: true,
          stdout: [...stdout],
          explanations: {
            eli5: `Loop pass #${idx + 1}: Python picks item \`${this.formatVal(itemVal)}\` from the list and puts it inside the box \`${node.iterVar}\`.`,
            beginner: `**For-Loop Iteration ${idx + 1}/${listItems.length}**: The loop variable \`${node.iterVar}\` is assigned \`${this.formatVal(itemVal)}\` (index ${idx} of \`${this.formatVal(listItems)}\`).`,
            deep: `Iterator advances to index ${idx}, binding loop target \`${node.iterVar}\` to \`${this.formatVal(itemVal)}\` in the current frame.`,
            whyItHappened: `There are still remaining items in \`${node.iterExpr}\` to iterate over.`
          }
        });

        const ret = this.executeBlock(node.body, callStack, functions, steps, stdout);
        if (ret && ret.returned) return ret;
      }

      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: node.text,
        eventType: "LOOP_END",
        scopes: this.snapshotScopes(callStack, null),
        evalBreakdown: `For-loop finished all ${listItems.length} items -> exiting loop`,
        branchResult: false,
        stdout: [...stdout],
        explanations: {
          eli5: `We've checked every single item in the list! The loop is done, so Python moves on past the loop.`,
          beginner: `The \`for\` loop has finished iterating through all ${listItems.length} elements of \`${node.iterExpr}\`. Execution exits the loop body.`,
          deep: `Iterator exhausted (\`StopIteration\`); control transfers to the first statement following the loop suite.`,
          whyItHappened: `All ${listItems.length} elements in \`${node.iterExpr}\` have been processed.`
        }
      });
      return null;
    }

    if (node.kind === "WHILE") {
      let guard = 0;
      while (guard < 100 && steps.length < this.maxSteps) {
        guard++;
        const condVal = Boolean(this.evalExpr(node.condition, activeFrame.vars, functions, callStack, steps, stdout, node.line));
        const substituted = this.substituteVarsInExpr(node.condition, activeFrame.vars);

        steps.push({
          stepIndex: steps.length + 1,
          line: node.line,
          codeText: node.text,
          eventType: condVal ? "LOOP_ITER" : "LOOP_END",
          scopes: this.snapshotScopes(callStack, null),
          evalBreakdown: `${node.condition}  ==>  ${substituted}  ==>  ${condVal ? "True (Continue Loop)" : "False (Exit Loop)"}`,
          branchResult: condVal,
          stdout: [...stdout],
          explanations: {
            eli5: condVal
              ? `Python checks the \`while\` rule: Is \`${substituted}\` true? Yes! So it runs the loop body again.`
              : `Python checks the \`while\` rule: Is \`${substituted}\` true? No (\`False\`)! The loop finally stops.`,
            beginner: condVal
              ? `While condition \`${node.condition}\` (\`${substituted}\`) is **True**. Entering loop iteration #${guard}.`
              : `While condition \`${node.condition}\` (\`${substituted}\`) is now **False**. Exiting the \`while\` loop.`,
            deep: `Loop predicate \`${node.condition}\` evaluated to \`${condVal ? "True" : "False"}\`.`,
            whyItHappened: `Current variable values make \`${substituted}\` evaluate to \`${condVal ? "True" : "False"}\`.`
          }
        });

        if (!condVal) break;
        const ret = this.executeBlock(node.body, callStack, functions, steps, stdout);
        if (ret && ret.returned) return ret;
      }
      return null;
    }

    if (node.kind === "STMT") {
      return this.executeSimpleStatement(node, callStack, functions, steps, stdout);
    }

    return null;
  }

  executeSimpleStatement(node, callStack, functions, steps, stdout) {
    const activeFrame = callStack[callStack.length - 1];
    const text = node.text;

    // 1. Return statement
    if (text === "return" || text.startsWith("return ")) {
      const expr = text === "return" ? "None" : text.slice(7).trim();
      const retVal = expr === "None" ? null : this.evalExpr(expr, activeFrame.vars, functions, callStack, steps, stdout, node.line);
      const substituted = this.substituteVarsInExpr(expr, activeFrame.vars);

      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: text,
        eventType: "RETURN",
        scopes: this.snapshotScopes(callStack, null),
        evalBreakdown: `return ${expr}  ==>  returns ${this.formatVal(retVal)}`,
        branchResult: null,
        stdout: [...stdout],
        explanations: {
          eli5: `The function finishes its job and hands back the answer \`${this.formatVal(retVal)}\` to whoever called it!`,
          beginner: `Returns value \`${this.formatVal(retVal)}\` (from \`${substituted}\`) and pops the \`${activeFrame.frameName}\` stack frame.`,
          deep: `Unwinds active activation record \`${activeFrame.frameName}\` and passes return value \`${this.formatVal(retVal)}\` to caller.`,
          whyItHappened: `A \`return\` statement immediately exits the current function with a result.`
        }
      });

      return { returned: true, value: retVal };
    }

    // 2. Print statement
    if (text.startsWith("print(") && text.endsWith(")")) {
      const inner = text.slice(6, -1).trim();
      const args = this.splitTopLevelArgs(inner);
      const evaluatedArgs = args.map((arg) =>
        this.evalExpr(arg, activeFrame.vars, functions, callStack, steps, stdout, node.line)
      );
      const outputLine = evaluatedArgs
        .map((v) => (typeof v === "string" ? v : this.formatVal(v)))
        .join(" ");

      stdout.push({
        stepIndex: steps.length + 1,
        line: node.line,
        text: outputLine
      });

      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: text,
        eventType: "PRINT",
        scopes: this.snapshotScopes(callStack, null),
        evalBreakdown: `Console Output -> "${outputLine}"`,
        branchResult: null,
        stdout: [...stdout],
        explanations: {
          eli5: `Python prints \`${outputLine}\` onto the screen so the user can see the result!`,
          beginner: `Evaluates the arguments inside \`print()\` and outputs \`"${outputLine}"\` to the console.`,
          deep: `Writes formatted string representation of evaluated arguments to standard output (\`stdout\`).`,
          whyItHappened: `\`print()\` sends current values to the program output panel.`
        }
      });
      return null;
    }

    // 3. List .append() method
    const appendMatch = text.match(/^([a-zA-Z_]\w*)\.append\((.*)\)$/);
    if (appendMatch) {
      const listName = appendMatch[1];
      const argExpr = appendMatch[2].trim();
      const itemVal = this.evalExpr(argExpr, activeFrame.vars, functions, callStack, steps, stdout, node.line);
      const currentList = Array.isArray(activeFrame.vars[listName]) ? [...activeFrame.vars[listName]] : [];
      const prevCopy = [...currentList];
      currentList.push(itemVal);
      activeFrame.prevVars[listName] = prevCopy;
      activeFrame.vars[listName] = currentList;

      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: text,
        eventType: "ASSIGN",
        scopes: this.snapshotScopes(callStack, {
          name: listName,
          status: "updated",
          prevValue: prevCopy
        }),
        evalBreakdown: `${listName}.append(${this.formatVal(itemVal)})  ==>  ${this.formatVal(currentList)}`,
        branchResult: null,
        stdout: [...stdout],
        explanations: {
          eli5: `Python adds \`${this.formatVal(itemVal)}\` to the end of the list \`${listName}\`!`,
          beginner: `Mutates list \`${listName}\` in-place by appending \`${this.formatVal(itemVal)}\` at index ${currentList.length - 1}.`,
          deep: `Invokes \`list.append\` method on \`${listName}\`, growing the list object to length ${currentList.length}.`,
          whyItHappened: `\`.append()\` adds a new element to the end of an existing list.`
        }
      });
      return null;
    }

    // 4. Augmented assignment (+=, -=, *=)
    const augMatch = text.match(/^([a-zA-Z_]\w*)\s*(\+=|-=|\*=)\s*(.+)$/);
    if (augMatch) {
      const varName = augMatch[1];
      const op = augMatch[2][0];
      const rhsExpr = augMatch[3].trim();
      const fullExpr = `${varName} ${op} (${rhsExpr})`;
      const prevVal = activeFrame.vars[varName];
      const newVal = this.evalExpr(fullExpr, activeFrame.vars, functions, callStack, steps, stdout, node.line);
      const substituted = `${this.formatVal(prevVal)} ${op} ${this.substituteVarsInExpr(rhsExpr, activeFrame.vars)}`;

      activeFrame.prevVars[varName] = prevVal;
      activeFrame.vars[varName] = newVal;

      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: text,
        eventType: "ASSIGN",
        scopes: this.snapshotScopes(callStack, {
          name: varName,
          status: "updated",
          prevValue: prevVal
        }),
        evalBreakdown: `${varName} = ${substituted}  ==>  ${this.formatVal(newVal)}`,
        branchResult: null,
        stdout: [...stdout],
        explanations: {
          eli5: `Python takes the old value of \`${varName}\` (\`${this.formatVal(prevVal)}\`), updates it using \`${op}\`, and stores the new value \`${this.formatVal(newVal)}\`!`,
          beginner: `Updates \`${varName}\` from \`${this.formatVal(prevVal)}\` to \`${this.formatVal(newVal)}\` by computing \`${substituted}\`.`,
          deep: `Evaluates augmented assignment \`${augMatch[2]}\` on \`${varName}\` and rebinds the identifier to \`${this.formatVal(newVal)}\`.`,
          whyItHappened: `\`${augMatch[2]}\` is shorthand for \`${varName} = ${varName} ${op} ${rhsExpr}\`.`
        }
      });
      return null;
    }

    // 5. Standard assignment: varName = expr
    const assignMatch = text.match(/^([a-zA-Z_]\w*)\s*=\s*(.+)$/);
    if (assignMatch && !text.includes("==")) {
      const varName = assignMatch[1];
      const rhsExpr = assignMatch[2].trim();
      const prevVal = activeFrame.vars[varName];
      const isNew = !(varName in activeFrame.vars);
      const substituted = this.substituteVarsInExpr(rhsExpr, activeFrame.vars);
      const newVal = this.evalExpr(rhsExpr, activeFrame.vars, functions, callStack, steps, stdout, node.line);

      activeFrame.prevVars[varName] = prevVal;
      activeFrame.vars[varName] = newVal;

      steps.push({
        stepIndex: steps.length + 1,
        line: node.line,
        codeText: text,
        eventType: "ASSIGN",
        scopes: this.snapshotScopes(callStack, {
          name: varName,
          status: isNew ? "new" : "updated",
          prevValue: prevVal
        }),
        evalBreakdown:
          substituted !== rhsExpr
            ? `${rhsExpr}  ==>  ${substituted}  ==>  ${this.formatVal(newVal)}`
            : `${ varName }  <--  ${this.formatVal(newVal)}`,
        branchResult: null,
        stdout: [...stdout],
        explanations: {
          eli5: isNew
            ? `Python creates a brand-new labeled box in memory called \`${varName}\` and puts \`${this.formatVal(newVal)}\` inside it!`
            : `Python calculates \`${substituted}\` (which equals \`${this.formatVal(newVal)}\`) and replaces the old value in \`${varName}\` (was \`${this.formatVal(prevVal)}\`).`,
          beginner: isNew
            ? `**Variable Initialized**: Evaluates the right side (\`${rhsExpr}\` $\\rightarrow$ \`${this.formatVal(newVal)}\`) and creates variable \`${varName}\` in \`${activeFrame.frameName}\`.`
            : `**Variable Updated**: Evaluates \`${rhsExpr}\` (\`${substituted}\` $\\rightarrow$ \`${this.formatVal(newVal)}\`) and updates \`${varName}\` from \`${this.formatVal(prevVal)}\` to \`${this.formatVal(newVal)}\`.`,
          deep: `Evaluates RHS expression \`${rhsExpr}\` to value \`${this.formatVal(newVal)}\` (type \`${this.getPythonType(newVal)}\`) and binds identifier \`${varName}\` in \`${activeFrame.frameName}\`.`,
          whyItHappened: `In Python, \`=\` always evaluates the right-hand side first, then stores the result in the variable on the left.`
        }
      });
      return null;
    }

    return null;
  }

  evalExpr(expr, scopeVars, functions, callStack, steps, stdout, lineNum) {
    const trimmed = expr.trim();

    // Check range(...)
    const rangeMatch = trimmed.match(/^range\((.+)\)$/);
    if (rangeMatch) {
      const parts = this.splitTopLevelArgs(rangeMatch[1]).map((a) =>
        Number(this.evalExpr(a, scopeVars, functions, callStack, steps, stdout, lineNum))
      );
      let start = 0,
        stop = 0,
        step = 1;
      if (parts.length === 1) {
        stop = parts[0];
      } else if (parts.length === 2) {
        start = parts[0];
        stop = parts[1];
      } else if (parts.length >= 3) {
        start = parts[0];
        stop = parts[1];
        step = parts[2] || 1;
      }
      const arr = [];
      if (step > 0) {
        for (let v = start; v < stop; v += step) arr.push(v);
      } else if (step < 0) {
        for (let v = start; v > stop; v += step) arr.push(v);
      }
      return arr;
    }

    // Check len(...)
    const lenMatch = trimmed.match(/^len\((.+)\)$/);
    if (lenMatch) {
      const target = this.evalExpr(lenMatch[1], scopeVars, functions, callStack, steps, stdout, lineNum);
      return target && typeof target.length === "number" ? target.length : 0;
    }

    // Check user-defined function call: funcName(arg1, arg2)
    const callMatch = trimmed.match(/^([a-zA-Z_]\w*)\((.*)\)$/);
    if (callMatch && functions[callMatch[1]]) {
      const fnNode = functions[callMatch[1]];
      const rawArgs = callMatch[2].trim() ? this.splitTopLevelArgs(callMatch[2]) : [];
      const argVals = rawArgs.map((a) =>
        this.evalExpr(a, scopeVars, functions, callStack, steps, stdout, lineNum)
      );

      const newFrameVars = {};
      fnNode.params.forEach((p, idx) => {
        newFrameVars[p] = argVals[idx];
      });

      const newFrame = {
        frameName: `${fnNode.funcName}(${fnNode.params.map((p, i) => `${p}=${this.formatVal(argVals[i])}`).join(", ")})`,
        vars: newFrameVars,
        prevVars: {}
      };

      callStack.push(newFrame);

      steps.push({
        stepIndex: steps.length + 1,
        line: fnNode.line,
        codeText: fnNode.text,
        eventType: "FUNC_CALL",
        scopes: this.snapshotScopes(callStack, null),
        evalBreakdown: `Calling ${newFrame.frameName} from line ${lineNum}`,
        branchResult: null,
        stdout: [...stdout],
        explanations: {
          eli5: `Python jumps into the \`${fnNode.funcName}\` recipe with inputs ${fnNode.params.map((p, i) => `\`${p}=${this.formatVal(argVals[i])}\``).join(", ")}!`,
          beginner: `**Function Call**: Pushes a new frame \`${newFrame.frameName}\` onto the Call Stack and binds parameters.`,
          deep: `Allocates new local activation record for \`${fnNode.funcName}\` on the call stack and binds formal parameters.`,
          whyItHappened: `Line ${lineNum} invoked \`${fnNode.funcName}(...)\`.`
        }
      });

      const res = this.executeBlock(fnNode.body, callStack, functions, steps, stdout);
      callStack.pop();
      return res && res.returned ? res.value : null;
    }

    // Replace Python operators/keywords for safe JS expression evaluation
    let jsExpr = trimmed
      .replace(/\/\//g, "___INTDIV___")
      .replace(/\band\b/g, "&&")
      .replace(/\bor\b/g, "||")
      .replace(/\bnot\s+/g, "!")
      .replace(/\bTrue\b/g, "true")
      .replace(/\bFalse\b/g, "false")
      .replace(/\bNone\b/g, "null");

    if (jsExpr.includes("___INTDIV___")) {
      const parts = jsExpr.split("___INTDIV___");
      if (parts.length === 2) {
        jsExpr = `Math.floor((${parts[0]}) / (${parts[1]}))`;
      }
    }

    const keys = Object.keys(scopeVars);
    const vals = keys.map((k) => scopeVars[k]);
    try {
      const fn = new Function(...keys, `return (${jsExpr});`);
      return fn(...vals);
    } catch (e) {
      throw { message: e.message, line: lineNum };
    }
  }

  substituteVarsInExpr(expr, scopeVars) {
    let result = expr;
    const sortedNames = Object.keys(scopeVars).sort((a, b) => b.length - a.length);
    for (const name of sortedNames) {
      const regex = new RegExp(`\\b${name}\\b`, "g");
      result = result.replace(regex, this.formatVal(scopeVars[name]));
    }
    return result;
  }

  splitTopLevelArgs(str) {
    if (!str.trim()) return [];
    const res = [];
    let current = "";
    let depth = 0;
    let inSingle = false;
    let inDouble = false;

    for (let i = 0; i < str.length; i++) {
      const ch = str[i];
      if (ch === "'" && !inDouble) inSingle = !inSingle;
      else if (ch === '"' && !inSingle) inDouble = !inDouble;
      else if (!inSingle && !inDouble) {
        if (ch === "(" || ch === "[") depth++;
        else if (ch === ")" || ch === "]") depth--;
        else if (ch === "," && depth === 0) {
          res.push(current.trim());
          current = "";
          continue;
        }
      }
      current += ch;
    }
    if (current.trim()) res.push(current.trim());
    return res;
  }

  snapshotScopes(callStack, changedVarInfo) {
    return callStack.map((frame, frameIdx) => {
      const isTopFrame = frameIdx === callStack.length - 1;
      const variables = Object.keys(frame.vars).map((varName) => {
        const val = frame.vars[varName];
        const isChangedHere = isTopFrame && changedVarInfo && changedVarInfo.name === varName;
        return {
          name: varName,
          type: this.getPythonType(val),
          value: Array.isArray(val) ? [...val] : val,
          formattedValue: this.formatVal(val),
          prevFormattedValue:
            isChangedHere && changedVarInfo.prevValue !== undefined
              ? this.formatVal(changedVarInfo.prevValue)
              : null,
          status: isChangedHere ? changedVarInfo.status : "unchanged"
        };
      });
      return {
        frameName: frame.frameName,
        isActive: isTopFrame,
        variables
      };
    });
  }

  getPythonType(val) {
    if (val === null || val === undefined) return "NoneType";
    if (Array.isArray(val)) return "list";
    if (typeof val === "boolean") return "bool";
    if (typeof val === "number") return Number.isInteger(val) ? "int" : "float";
    if (typeof val === "string") return "str";
    return typeof val;
  }

  formatVal(val) {
    if (val === null || val === undefined) return "None";
    if (typeof val === "boolean") return val ? "True" : "False";
    if (typeof val === "string") return `"${val}"`;
    if (Array.isArray(val)) return `[${val.map((v) => this.formatVal(v)).join(", ")}]`;
    return String(val);
  }

  describeUpcomingAction(nextStep) {
    switch (nextStep.eventType) {
      case "ASSIGN":
        return "compute and update a variable in memory";
      case "CONDITION":
        return "test a conditional expression (True/False)";
      case "LOOP_ITER":
        return "start the next loop iteration";
      case "LOOP_END":
        return "finish the loop and move forward";
      case "PRINT":
        return "print output to the console";
      case "FUNC_CALL":
        return "call a function and create a new stack frame";
      case "RETURN":
        return "return a result from the function";
      default:
        return "execute the statement";
    }
  }

  generateQuizForStep(currentStep, nextStep) {
    if (!nextStep) return null;
    if (nextStep.eventType === "CONDITION") {
      return {
        question: `Prediction Challenge: On Line ${nextStep.line} (\`${nextStep.codeText}\`), what will the condition evaluate to?`,
        options: [
          { label: "True (Enter the block)", isCorrect: nextStep.branchResult === true },
          { label: "False (Skip the block)", isCorrect: nextStep.branchResult === false }
        ],
        explanation: nextStep.evalBreakdown
      };
    }
    if (nextStep.eventType === "ASSIGN") {
      const activeScope = nextStep.scopes[nextStep.scopes.length - 1];
      const changed = activeScope.variables.find((v) => v.status !== "unchanged");
      if (changed) {
        const correctVal = changed.formattedValue;
        const fake1 = typeof changed.value === "number" ? String(changed.value + 1) : `"None"`;
        const fake2 = typeof changed.value === "number" ? String(changed.value * 2 + 3) : `0`;
        const options = [
          { label: `${changed.name} = ${correctVal}`, isCorrect: true },
          { label: `${changed.name} = ${fake1}`, isCorrect: false },
          { label: `${changed.name} = ${fake2}`, isCorrect: false }
        ].sort(() => Math.random() - 0.5);
        return {
          question: `Prediction Challenge: After Line ${nextStep.line} (\`${nextStep.codeText}\`) runs, what will \`${changed.name}\` be?`,
          options,
          explanation: nextStep.evalBreakdown
        };
      }
    }
    return null;
  }

  buildControlFlowGraph(statements) {
    const nodes = [];
    const edges = [];

    const addNode = (id, label, type, line) => {
      nodes.push({ id, label, type, line });
      return id;
    };

    const startId = addNode("start", "START PROGRAM", "start", 0);

    const buildList = (stmts, prevIds) => {
      let currentPrevs = prevIds;
      for (const s of stmts) {
        if (s.kind === "IF_CHAIN") {
          const exitIds = [];
          let condPrevIds = currentPrevs;
          for (const br of s.branches) {
            if (br.type === "else") {
              const bodyEnd = buildList(br.body, condPrevIds);
              exitIds.push(...bodyEnd);
              condPrevIds = [];
            } else {
              const cid = addNode(`L${br.line}`, `${br.type.toUpperCase()}: ${br.condition}`, "condition", br.line);
              condPrevIds.forEach((p) => edges.push({ from: p, to: cid, label: p.startsWith("L") ? "" : "" }));
              const bodyEnd = buildList(br.body, [cid]);
              exitIds.push(...bodyEnd);
              condPrevIds = [cid];
            }
          }
          currentPrevs = [...exitIds, ...condPrevIds];
        } else if (s.kind === "FOR" || s.kind === "WHILE") {
          const label = s.kind === "FOR" ? `FOR ${s.iterVar} in ${s.iterExpr}` : `WHILE ${s.condition}`;
          const loopId = addNode(`L${s.line}`, label, "loop", s.line);
          currentPrevs.forEach((p) => edges.push({ from: p, to: loopId }));
          const bodyEnd = buildList(s.body, [loopId]);
          bodyEnd.forEach((b) => edges.push({ from: b, to: loopId, isBackEdge: true }));
          currentPrevs = [loopId];
        } else {
          const nid = addNode(
            `L${s.line}`,
            s.text.length > 28 ? s.text.slice(0, 26) + ".." : s.text,
            s.text.startsWith("print(") ? "output" : s.kind === "DEF" ? "func" : "stmt",
            s.line
          );
          currentPrevs.forEach((p) => edges.push({ from: p, to: nid }));
          currentPrevs = [nid];
        }
      }
      return currentPrevs;
    };

    const lastIds = buildList(statements, [startId]);
    const endId = addNode("end", "END PROGRAM", "end", 9999);
    lastIds.forEach((p) => edges.push({ from: p, to: endId }));

    return { nodes, edges };
  }
}

window.PRESET_EXAMPLES = PRESET_EXAMPLES;
window.PythonFlowTracer = PythonFlowTracer;

// AI-Powered Code Flow Visualizer - Interactive Application Controller

class CodeFlowVisualizerApp {
  constructor() {
    this.tracer = new window.PythonFlowTracer();
    this.currentPresetKey = "for_loop_sum";
    this.sourceCode = window.PRESET_EXAMPLES[this.currentPresetKey].code;

    this.traceResult = null;
    this.currentStepIdx = 0; // 0-indexed into traceResult.steps
    this.isPlaying = false;
    this.playInterval = null;
    this.playSpeedMs = 1100;
    this.explanationDepth = "beginner"; // 'eli5' | 'beginner' | 'deep'
    this.quizModeEnabled = false;
    this.isEditingCode = false;

    this.initDOM();
    this.bindEvents();
    this.loadPreset(this.currentPresetKey);
  }

  initDOM() {
    this.presetSelect = document.getElementById("presetSelect");
    this.btnEditToggle = document.getElementById("btnEditToggle");
    this.btnRunTrace = document.getElementById("btnRunTrace");
    this.btnQuizMode = document.getElementById("btnQuizMode");

    // Transport controls
    this.btnFirst = document.getElementById("btnFirst");
    this.btnPrev = document.getElementById("btnPrev");
    this.btnPlay = document.getElementById("btnPlay");
    this.btnNext = document.getElementById("btnNext");
    this.btnLast = document.getElementById("btnLast");
    this.timelineSlider = document.getElementById("timelineSlider");
    this.stepCounter = document.getElementById("stepCounter");
    this.speedPills = document.querySelectorAll(".speed-pill");

    // Left Panel: Code & Console
    this.codeTraceView = document.getElementById("codeTraceView");
    this.codeEditorTextarea = document.getElementById("codeEditorTextarea");
    this.consoleBody = document.getElementById("consoleBody");

    // Center Panel: CFG Flowchart & Memory
    this.flowSvgContainer = document.getElementById("flowSvgContainer");
    this.memoryScroll = document.getElementById("memoryScroll");
    this.frameCountBadge = document.getElementById("frameCountBadge");

    // Right Panel: AI Tutor
    this.depthBtns = document.querySelectorAll(".depth-btn");
    this.eventBadge = document.getElementById("eventBadge");
    this.stepLineBadge = document.getElementById("stepLineBadge");
    this.stepCodePreview = document.getElementById("stepCodePreview");
    this.evalBreakdownBox = document.getElementById("evalBreakdownBox");
    this.whatHappenedText = document.getElementById("whatHappenedText");
    this.whyHappenedText = document.getElementById("whyHappenedText");
    this.whatNextText = document.getElementById("whatNextText");

    // Quiz & AI Q&A
    this.quizCard = document.getElementById("quizCard");
    this.quizQuestion = document.getElementById("quizQuestion");
    this.quizOptions = document.getElementById("quizOptions");
    this.chatInput = document.getElementById("chatInput");
    this.btnAskAi = document.getElementById("btnAskAi");
    this.aiAnswerBubble = document.getElementById("aiAnswerBubble");
    this.quickChips = document.querySelectorAll(".chip-btn");

    // Populate Preset Selector
    Object.entries(window.PRESET_EXAMPLES).forEach(([key, item]) => {
      const opt = document.createElement("option");
      opt.value = key;
      opt.textContent = item.title;
      this.presetSelect.appendChild(opt);
    });
  }

  bindEvents() {
    this.presetSelect.addEventListener("change", (e) => {
      this.loadPreset(e.target.value);
    });

    this.btnEditToggle.addEventListener("click", () => {
      this.toggleEditMode(!this.isEditingCode);
    });

    this.btnRunTrace.addEventListener("click", () => {
      if (this.isEditingCode) {
        this.sourceCode = this.codeEditorTextarea.value;
        this.toggleEditMode(false);
      }
      this.runVisualization();
    });

    this.btnQuizMode.addEventListener("click", () => {
      this.quizModeEnabled = !this.quizModeEnabled;
      this.btnQuizMode.classList.toggle("active", this.quizModeEnabled);
      this.btnQuizMode.textContent = this.quizModeEnabled
        ? "Quiz Mode: ON"
        : "Predict Next Step";
      this.renderStep();
    });

    // Transport buttons
    this.btnFirst.addEventListener("click", () => {
      this.pause();
      this.goToStep(0);
    });

    this.btnPrev.addEventListener("click", () => {
      this.pause();
      this.goToStep(this.currentStepIdx - 1);
    });

    this.btnPlay.addEventListener("click", () => {
      if (this.isPlaying) this.pause();
      else this.play();
    });

    this.btnNext.addEventListener("click", () => {
      this.pause();
      this.goToStep(this.currentStepIdx + 1);
    });

    this.btnLast.addEventListener("click", () => {
      this.pause();
      if (this.traceResult && this.traceResult.steps.length > 0) {
        this.goToStep(this.traceResult.steps.length - 1);
      }
    });

    this.timelineSlider.addEventListener("input", (e) => {
      this.pause();
      this.goToStep(Number(e.target.value));
    });

    // Keyboard shortcuts (Left/Right arrows, Space to play/pause)
    window.addEventListener("keydown", (e) => {
      if (
        document.activeElement === this.codeEditorTextarea ||
        document.activeElement === this.chatInput
      ) {
        return;
      }
      if (e.key === "ArrowRight") {
        e.preventDefault();
        this.pause();
        this.goToStep(this.currentStepIdx + 1);
      } else if (e.key === "ArrowLeft") {
        e.preventDefault();
        this.pause();
        this.goToStep(this.currentStepIdx - 1);
      } else if (e.key === " ") {
        e.preventDefault();
        if (this.isPlaying) this.pause();
        else this.play();
      }
    });

    // Speed pills
    this.speedPills.forEach((pill) => {
      pill.addEventListener("click", () => {
        this.speedPills.forEach((p) => p.classList.remove("active"));
        pill.classList.add("active");
        this.playSpeedMs = Number(pill.dataset.speed);
        if (this.isPlaying) {
          this.pause();
          this.play();
        }
      });
    });

    // Explanation depth buttons
    this.depthBtns.forEach((btn) => {
      btn.addEventListener("click", () => {
        this.depthBtns.forEach((b) => b.classList.remove("active"));
        btn.classList.add("active");
        this.explanationDepth = btn.dataset.depth;
        this.renderStep();
      });
    });

    // AI Tutor Q&A
    this.btnAskAi.addEventListener("click", () => this.handleAskAI());
    this.chatInput.addEventListener("keydown", (e) => {
      if (e.key === "Enter") this.handleAskAI();
    });

    this.quickChips.forEach((chip) => {
      chip.addEventListener("click", () => {
        this.chatInput.value = chip.dataset.question;
        this.handleAskAI();
      });
    });
  }

  loadPreset(key) {
    this.pause();
    this.currentPresetKey = key;
    this.sourceCode = window.PRESET_EXAMPLES[key].code;
    this.codeEditorTextarea.value = this.sourceCode;
    this.toggleEditMode(false);
    this.runVisualization();
  }

  toggleEditMode(editing) {
    this.isEditingCode = editing;
    if (editing) {
      this.pause();
      this.codeEditorTextarea.value = this.sourceCode;
      this.codeEditorTextarea.classList.remove("hidden");
      this.codeTraceView.classList.add("hidden");
      this.btnEditToggle.textContent = "Cancel Edit";
    } else {
      this.codeEditorTextarea.classList.add("hidden");
      this.codeTraceView.classList.remove("hidden");
      this.btnEditToggle.textContent = "Edit Code";
    }
  }

  runVisualization() {
    this.pause();
    this.traceResult = this.tracer.trace(this.sourceCode);
    const total = this.traceResult.steps.length;
    this.timelineSlider.max = Math.max(0, total - 1);
    this.currentStepIdx = 0;
    this.aiAnswerBubble.classList.add("hidden");
    this.renderStep();
  }

  goToStep(idx) {
    if (!this.traceResult || this.traceResult.steps.length === 0) return;
    const clamped = Math.max(0, Math.min(idx, this.traceResult.steps.length - 1));
    this.currentStepIdx = clamped;
    this.renderStep();
  }

  play() {
    if (!this.traceResult || this.traceResult.steps.length === 0) return;
    if (this.currentStepIdx >= this.traceResult.steps.length - 1) {
      this.currentStepIdx = 0;
    }
    this.isPlaying = true;
    this.btnPlay.classList.add("playing");
    this.btnPlay.textContent = "Pause";

    this.playInterval = setInterval(() => {
      if (this.currentStepIdx < this.traceResult.steps.length - 1) {
        this.currentStepIdx++;
        this.renderStep();
      } else {
        this.pause();
      }
    }, this.playSpeedMs);
  }

  pause() {
    this.isPlaying = false;
    if (this.playInterval) {
      clearInterval(this.playInterval);
      this.playInterval = null;
    }
    this.btnPlay.classList.remove("playing");
    this.btnPlay.textContent = "Play";
  }

  renderStep() {
    if (!this.traceResult || this.traceResult.steps.length === 0) return;
    const steps = this.traceResult.steps;
    const step = steps[this.currentStepIdx];
    const total = steps.length;

    // Update scrubber and transport controls
    this.timelineSlider.value = this.currentStepIdx;
    this.stepCounter.textContent = `Step ${this.currentStepIdx + 1} / ${total}`;
    this.btnFirst.disabled = this.currentStepIdx === 0;
    this.btnPrev.disabled = this.currentStepIdx === 0;
    this.btnNext.disabled = this.currentStepIdx >= total - 1;
    this.btnLast.disabled = this.currentStepIdx >= total - 1;

    this.renderCodeLines(step);
    this.renderConsoleOutput(step);
    this.renderFlowchartSVG(step);
    this.renderMemoryScopes(step);
    this.renderAITutorPanel(step);
  }

  renderCodeLines(step) {
    const visitedLines = new Set();
    for (let i = 0; i <= this.currentStepIdx; i++) {
      visitedLines.add(this.traceResult.steps[i].line);
    }

    const activeScope = step.scopes[step.scopes.length - 1];
    const changedVar = activeScope
      ? activeScope.variables.find((v) => v.status !== "unchanged")
      : null;

    this.codeTraceView.innerHTML = "";
    this.traceResult.rawLines.forEach((rawLine, idx) => {
      const lineNum = idx + 1;
      const isCurrent = step.line === lineNum;
      const isNext = step.nextLine === lineNum && !isCurrent;
      const isVisited = visitedLines.has(lineNum);

      const row = document.createElement("div");
      row.className = "code-line";
      if (isCurrent) row.classList.add("is-current");
      if (isNext) row.classList.add("is-next");
      if (isVisited) row.classList.add("is-visited");

      const arrowSymbol = isCurrent ? "▶" : isNext ? "↳" : "";
      const arrowColor = isCurrent ? "#818cf8" : "#f59e0b";

      let inlineBadgeHTML = "";
      if (isCurrent) {
        if (changedVar) {
          inlineBadgeHTML = `<span class="inline-pill">${changedVar.name} = ${changedVar.formattedValue}</span>`;
        } else if (step.branchResult !== null) {
          const cls = step.branchResult ? "branch-true" : "branch-false";
          inlineBadgeHTML = `<span class="inline-pill ${cls}">${step.branchResult ? "✓ True" : "✗ False"}</span>`;
        }
      }

      row.innerHTML = `
        <div class="line-gutter">
          <span class="line-arrow" style="color:${arrowColor}">${arrowSymbol}</span>
          <span class="line-num">${lineNum}</span>
        </div>
        <div class="line-code">${this.escapeHTML(rawLine)}</div>
        <div class="line-inline-values">${inlineBadgeHTML}</div>
      `;

      row.addEventListener("click", () => {
        const targetIdx = this.traceResult.steps.findIndex((s) => s.line === lineNum);
        if (targetIdx !== -1) {
          this.pause();
          this.goToStep(targetIdx);
        }
      });

      this.codeTraceView.appendChild(row);
    });
  }

  renderConsoleOutput(step) {
    this.consoleBody.innerHTML = "";
    if (!step.stdout || step.stdout.length === 0) {
      this.consoleBody.innerHTML = `<div class="empty-state">No console output yet at Step ${step.stepIndex}.</div>`;
      return;
    }

    step.stdout.forEach((item) => {
      const lineDiv = document.createElement("div");
      lineDiv.className = "console-line";
      if (item.stepIndex === step.stepIndex) {
        lineDiv.classList.add("new-output");
      }
      lineDiv.innerHTML = `
        <span class="console-step-tag">[Step ${item.stepIndex} | L${item.line}]</span>
        <span>${this.escapeHTML(item.text)}</span>
      `;
      this.consoleBody.appendChild(lineDiv);
    });
    this.consoleBody.scrollTop = this.consoleBody.scrollHeight;
  }

  renderFlowchartSVG(step) {
    const cfg = this.traceResult.cfg;
    if (!cfg || !cfg.nodes.length) return;

    const nodeW = 190;
    const nodeH = 38;
    const vGap = 58;
    const svgW = 360;
    const svgH = Math.max(260, cfg.nodes.length * vGap + 40);

    const positions = {};
    cfg.nodes.forEach((n, idx) => {
      positions[n.id] = {
        x: svgW / 2,
        y: 30 + idx * vGap
      };
    });

    const activeNodeId = `L${step.line}`;
    const nextNodeId = step.nextLine ? `L${step.nextLine}` : "end";

    let edgesSVG = "";
    cfg.edges.forEach((edge) => {
      const p1 = positions[edge.from];
      const p2 = positions[edge.to];
      if (!p1 || !p2) return;

      const isTransition = edge.from === activeNodeId && edge.to === nextNodeId;
      const stroke = isTransition ? "#f59e0b" : edge.isBackEdge ? "#6366f1" : "#334155";
      const strokeWidth = isTransition ? 2.5 : 1.5;

      if (edge.isBackEdge || p2.y <= p1.y) {
        const curveX = 36;
        edgesSVG += `<path d="M ${p1.x - nodeW / 2} ${p1.y} C ${curveX} ${p1.y}, ${curveX} ${p2.y}, ${p2.x - nodeW / 2} ${p2.y}" fill="none" stroke="${stroke}" stroke-width="${strokeWidth}" stroke-dasharray="4 3" />`;
      } else {
        edgesSVG += `<line x1="${p1.x}" y1="${p1.y + nodeH / 2}" x2="${p2.x}" y2="${p2.y - nodeH / 2}" stroke="${stroke}" stroke-width="${strokeWidth}" />`;
      }
    });

    let nodesSVG = "";
    cfg.nodes.forEach((node) => {
      const pos = positions[node.id];
      const isCurrent = node.line === step.line;
      const isNext = node.line === step.nextLine;

      let fill = "#1e293b";
      let stroke = "#334155";
      if (node.type === "start" || node.type === "end") {
        fill = "#0f172a";
        stroke = "#475569";
      } else if (node.type === "condition" || node.type === "loop") {
        fill = "#1e1b4b";
        stroke = "#6366f1";
      }

      if (isCurrent) {
        fill = "#312e81";
        stroke = "#818cf8";
      } else if (isNext) {
        stroke = "#f59e0b";
      }

      const rx = node.type === "start" || node.type === "end" ? 19 : 7;
      nodesSVG += `
        <g transform="translate(${pos.x - nodeW / 2}, ${pos.y - nodeH / 2})" style="cursor:pointer" data-line="${node.line}">
          <rect width="${nodeW}" height="${nodeH}" rx="${rx}" fill="${fill}" stroke="${stroke}" stroke-width="${isCurrent ? 2.5 : 1.5}" />
          <text x="${nodeW / 2}" y="${nodeH / 2 + 4}" text-anchor="middle" fill="#f8fafc" font-family="JetBrains Mono, monospace" font-size="11" font-weight="${isCurrent ? "700" : "500"}">
            ${this.escapeHTML(node.label)}
          </text>
        </g>
      `;
    });

    this.flowSvgContainer.innerHTML = `
      <svg width="${svgW}" height="${svgH}" viewBox="0 0 ${svgW} ${svgH}">
        ${edgesSVG}
        ${nodesSVG}
      </svg>
    `;
  }

  renderMemoryScopes(step) {
    this.memoryScroll.innerHTML = "";
    const scopes = step.scopes || [];
    this.frameCountBadge.textContent = `${scopes.length} Frame${scopes.length > 1 ? "s" : ""}`;

    // Render from top of call stack down
    [...scopes].reverse().forEach((scope) => {
      const card = document.createElement("div");
      card.className = "scope-card";

      const header = document.createElement("div");
      header.className = `scope-header ${scope.isActive ? "active-frame" : ""}`;
      header.innerHTML = `
        <span>${this.escapeHTML(scope.frameName)}</span>
        <span>${scope.isActive ? "● ACTIVE SCOPE" : "CALLER"}</span>
      `;
      card.appendChild(header);

      const varList = document.createElement("div");
      varList.className = "var-list";

      if (scope.variables.length === 0) {
        varList.innerHTML = `<div class="empty-state" style="padding:8px;">No variables initialized yet in this frame.</div>`;
      } else {
        // Detect if there's an index variable 'i' or 'best_index' for highlighting array cells
        const idxVar = scope.variables.find((v) =>
          ["i", "idx", "index", "k"].includes(v.name) && typeof v.value === "number"
        );
        const activeIdxVal = idxVar ? idxVar.value : null;

        scope.variables.forEach((v) => {
          const item = document.createElement("div");
          item.className = "var-item";
          if (v.status === "updated") item.classList.add("var-changed");
          if (v.status === "new") item.classList.add("var-new");

          let badgeHTML = "";
          if (v.status === "new") {
            badgeHTML = `<span class="var-badge-change new">NEW</span>`;
          } else if (v.status === "updated") {
            badgeHTML = `<span class="var-badge-change updated">UPDATED</span>`;
          }

          let valDiffHTML = `<span class="var-curr-val">${this.escapeHTML(v.formattedValue)}</span>`;
          if (v.status === "updated" && v.prevFormattedValue !== null) {
            valDiffHTML = `
              <span class="var-prev-val">${this.escapeHTML(v.prevFormattedValue)}</span>
              <span class="var-arrow">→</span>
              <span class="var-curr-val">${this.escapeHTML(v.formattedValue)}</span>
            `;
          }

          let arrayVisualizerHTML = "";
          if (Array.isArray(v.value)) {
            const cells = v.value
              .map((cellVal, cIdx) => {
                const isPointed = activeIdxVal === cIdx;
                return `
                  <div class="array-cell ${isPointed ? "active-index" : ""}">
                    <span class="array-cell-idx">[${cIdx}]</span>
                    <span class="array-cell-val">${this.escapeHTML(String(cellVal))}</span>
                  </div>
                `;
              })
              .join("");
            arrayVisualizerHTML = `<div class="array-cells">${cells}</div>`;
          }

          item.innerHTML = `
            <div class="var-top-row">
              <div class="var-name-group">
                <span class="var-name">${this.escapeHTML(v.name)}</span>
                <span class="var-type">${v.type}</span>
              </div>
              ${badgeHTML}
            </div>
            <div class="var-value-row">
              ${valDiffHTML}
            </div>
            ${arrayVisualizerHTML}
          `;
          varList.appendChild(item);
        });
      }

      card.appendChild(varList);
      this.memoryScroll.appendChild(card);
    });
  }

  renderAITutorPanel(step) {
    this.eventBadge.textContent = step.eventType.replace("_", " ");
    this.stepLineBadge.textContent = `Line ${step.line}`;
    this.stepCodePreview.textContent = step.codeText;
    this.evalBreakdownBox.textContent = step.evalBreakdown;

    const mainExplanation =
      step.explanations[this.explanationDepth] || step.explanations.beginner;

    this.whatHappenedText.innerHTML = this.formatMarkdownCode(mainExplanation);
    this.whyHappenedText.innerHTML = this.formatMarkdownCode(
      step.explanations.whyItHappened || ""
    );
    this.whatNextText.innerHTML = this.formatMarkdownCode(
      step.explanations.whatNext || ""
    );

    // Render Prediction Quiz if enabled and available
    if (this.quizModeEnabled && step.quiz) {
      this.quizCard.classList.remove("hidden");
      this.quizQuestion.innerHTML = this.formatMarkdownCode(step.quiz.question);
      this.quizOptions.innerHTML = "";
      step.quiz.options.forEach((opt) => {
        const btn = document.createElement("button");
        btn.className = "quiz-option-btn";
        btn.textContent = opt.label;
        btn.addEventListener("click", () => {
          btn.classList.add(opt.isCorrect ? "correct" : "wrong");
          btn.textContent = `${opt.label} ${opt.isCorrect ? "✓ Correct!" : "✗ Try again"}`;
        });
        this.quizOptions.appendChild(btn);
      });
    } else {
      this.quizCard.classList.add("hidden");
    }
  }

  handleAskAI() {
    const q = this.chatInput.value.trim();
    if (!q || !this.traceResult) return;

    const step = this.traceResult.steps[this.currentStepIdx];
    const activeScope = step.scopes[step.scopes.length - 1];
    const varsSummary = activeScope.variables
      .map((v) => `\`${v.name} = ${v.formattedValue}\``)
      .join(", ");

    let answer = "";
    const lower = q.toLowerCase();

    if (lower.includes("why") || lower.includes("skip") || lower.includes("branch")) {
      answer = `**Why this happened on Line ${step.line}:** ${step.explanations.whyItHappened} Specifically, Python evaluated \`${step.evalBreakdown}\`.`;
    } else if (lower.includes("variable") || lower.includes("memory") || lower.includes("value")) {
      answer = `**Memory State at Step ${step.stepIndex}:** In \`${activeScope.frameName}\`, the current variables are: ${varsSummary || "none yet"}.`;
    } else if (lower.includes("next")) {
      answer = `**Up Next:** ${step.explanations.whatNext}`;
    } else if (lower.includes("loop")) {
      answer = `**How Loops Work Here:** A loop repeats its indented block until its condition becomes \`False\` or all list items are visited. On this step: ${step.explanations.beginner}`;
    } else {
      answer = `**AI Tutor (Step ${step.stepIndex}, Line ${step.line}):** ${step.explanations.eli5} Current evaluation: \`${step.evalBreakdown}\`. Variables in memory: ${varsSummary || "none"}.`;
    }

    this.aiAnswerBubble.innerHTML = this.formatMarkdownCode(answer);
    this.aiAnswerBubble.classList.remove("hidden");
    this.chatInput.value = "";
  }

  formatMarkdownCode(str) {
    if (!str) return "";
    return this.escapeHTML(str)
      .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
      .replace(/`([^`]+)`/g, "<code>$1</code>");
  }

  escapeHTML(str) {
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
  }
}

window.addEventListener("DOMContentLoaded", () => {
  window.visualizerApp = new CodeFlowVisualizerApp();
});
